{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Compound 12 showed a brain concentration of 3180 ng/g at 1 h after oral administration of 10 mg/kg in rats, indicating meaningful in vivo CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The PET tracer [11C]PXT012253 showed rapid uptake in non-human primate brain, reaching a peak SUV of about five within five minutes after tracer administration, supporting good BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DB766 showed brain concentrations much lower than or close to plasma concentrations after i.v. and p.o. administration in mice, indicating limited brain uptake in this analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct in vivo and PET records in rodents and NHPs demonstrate rapid brain uptake and high brain concentrations after systemic administration, outweighing the limited brain uptake seen in the closest negative analog. Overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "The two most similar evidence records conflict (C03 negative vs C05 positive), creating uncertainty in direct analog transfer.",
    "No query-matched quantitative CSF or unbound brain-to-plasma data are available; PET and total brain concentration data do not fully define free brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

